SELECT format($fmt$SELECT %L || '|' || count(*) || '|' || md5(COALESCE(string_agg(payload, E'\n' ORDER BY payload COLLATE "C"), '')) FROM (SELECT row_to_json(r)::text payload FROM (SELECT * FROM %I.%I WHERE "CompanyId" IN (SELECT "Id" FROM "Companies" WHERE "Slug" IN ('santa','farma'))) r) x;$fmt$,t.table_name,t.table_schema,t.table_name) FROM information_schema.tables t WHERE t.table_schema='public' AND t.table_type='BASE TABLE' AND EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema=t.table_schema AND c.table_name=t.table_name AND c.column_name='CompanyId') ORDER BY t.table_name
\gexec
SELECT 'companies|' || md5(string_agg(row_to_json(c)::text,E'\n' ORDER BY c."Id")) FROM "Companies" c WHERE c."Slug" IN ('santa','farma');
SELECT 'shared_identity|' || md5(string_agg(concat_ws('|',u."Id"::text,u."PasswordHash",u."SecurityStamp",u."TwoFactorEnabled"::text),E'\n' ORDER BY u."Id")) FROM "AspNetUsers" u WHERE u."Id" IN (SELECT "UserId" FROM "CompanyMemberships" WHERE "CompanyId" IN (SELECT "Id" FROM "Companies" WHERE "Slug" IN ('santa','farma')));